+import React, { useEffect } from "react";
+
+import AccessibleButton from "../elements/AccessibleButton";
+import IconizedContextMenu from "./IconizedContextMenu";
+import { useContextMenu } from "../../structures/ContextMenu";
+import UIStore from "../../../stores/UIStore";
+
+interface Props extends Omit<React.ComponentProps<typeof AccessibleButton<"button">>, "onClick" | "children"> {
+    options: React.ReactNode[];
+    title: string;
+}
+
+export const KebabContextMenu: React.FC<Props> = ({ options, title, disabled, ...buttonProps }) => {
+    const [isOpen, buttonRef, open, close] = useContextMenu<HTMLButtonElement>();
+
+    useEffect(() => {
+        if (disabled && isOpen) close();
+    }, [disabled, isOpen]); // eslint-disable-line react-hooks/exhaustive-deps
+
+    const rect = isOpen ? buttonRef.current?.getBoundingClientRect() : undefined;
+
+    return <>
+        <AccessibleButton
+            {...buttonProps}
+            element="button"
+            type="button"
+            inputRef={buttonRef}
+            className="mx_KebabContextMenu_button"
+            title={title}
+            aria-label={title}
+            aria-haspopup="true"
+            aria-expanded={isOpen}
+            aria-disabled={disabled}
+            disabled={disabled}
+            onClick={(ev) => {
+                buttonRef.current?.focus();
+                open(ev);
+            }}
+        >
+            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
+        </AccessibleButton>
+        { isOpen && rect && <IconizedContextMenu
+            right={UIStore.instance.windowWidth - rect.right - window.scrollX}
+            top={rect.bottom + window.scrollY}
+            rightAligned
+            onFinished={close}
+        >
+            { options.map((option, index) => React.isValidElement(option)
+                ? React.cloneElement(option as React.ReactElement<{ onClick?: (ev: React.SyntheticEvent) => void }>, {
+                    key: index,
+                    onClick: (ev) => {
+                        option.props.onClick?.(ev);
+                        close();
+                    },
+                })
+                : option) }
+        </IconizedContextMenu> }
+    </>;
+};
+
+export default KebabContextMenu;
